 b.obs('b00014','Rectal temperature',38.5,kind='vital',unit='ºC',flag='normal',quote='was normothermic with a rectal temperature of 38.5 ºC')
 for name,q in [('Hydration','properly hydrated'),('Mucous membranes','pink mucous membranes'),('Abdominal palpation','Abdominal palpation did not reveal any abnormalities'),('Cardiac auscultation','Cardiac auscultation was within normal limits.'),('Respiratory sounds','Respiratory sounds were also normal')]:b.obs('b00014',name,kind='physiologic',text_value=q,flag='normal',quote=q)
 for name,q in [('Organomegaly','there was absence of organomegaly'),('Palpable abdominal masses','there was absence of organomegaly or the presence of palpable masses'),('Abdominal pain','no abdominal pain'),('Lymph node enlargement','there was no evidence of lymph node enlargement')]:b.symptom('b00014',name,q,assertion='absent',kind='sign' if name!='Abdominal pain' else 'symptom')
 b.symptom('b00001','Asymptomatic',quote='asymptomatic stray cat',kind='functional_status',text_value='asymptomatic')
