 for n,m in [('D. immitis antigen','SNAP Pro Analyzer rapid test'),('D. immitis antigen','DiroCheck ELISA'),('Anti-D. immitis antibodies','in-house Dit33 recombinant protein ELISA')]:b.fact('observations','b00060',n+' not detected using '+m,{'name':n,'kind':'laboratory','status':'resulted','flag':'negative','method':m},extra_ev=b.evidence('b00010'))
 for spec in ['nematodes extracted from spermatic cord','microfilariae in EDTA-blood sample']:b.obs('b00061','D. repens PCR',kind='microbiology',flag='positive',method='rt-PCR panfilarial-4-species',specimen=spec)
 b.obs('b00062','Adult female nematode microscopic morphology',kind='microbiology',text_value='Two females: thick cuticle, spaced longitudinal surface ridges, large lateral chords, polymyariancoelomyarian musculature, small intestine, paired uteri with morulae and microfilariae',specimen='parasites removed from cat',subject='other')
 dx=b.cond('b00004','Naturally acquired subcutaneous dirofilariosis due to D. repens',body_site='spermatic cord',diagnostic_basis='morphology and PCR',extra_ev=None) if False else b.fact('conditions','b00004','Naturally acquired D. repens subcutaneous dirofilariosis',{'name':'D. repens subcutaneous dirofilariosis','verification_status':'confirmed','role':'primary_diagnosis','body_site':'spermatic cord','diagnostic_basis':'morphology and PCR'},extra_ev=b.evidence('b00061'))
 e1=b.event('Capture for sterilization',[c,age,sex],'b00005','July 2023');e2=b.event('Nematodes incidentally removed during sterilization',[surg],'b00005','During the surgical procedure');e3=b.event('D. repens confirmed molecularly',[dx],'b00061');b.relation(e1,e2,'b00005');b.relation(e2,e3,'b00061')
 b.summary('Adult intact male stray cat captured in Spain for sterilization was asymptomatic with an unremarkable examination.',[c,age,sex]+[f['fact_id'] for f in p['facts'] if f['task']=='symptoms_function'])
