 rise=b.obs('b00050','CoMET scores escalation',kind='physiologic',text_value='escalation starting around 9 am',time={'text':'around 9 am','relation':'at','anchor':'CoMET escalation'},quote='Note the escalation in CoMET scores starting around 9 am with the subsequent diagnosis of NEC occurring around 12 pm.')
 diag=b.fact('conditions','b00050','NEC diagnosed around 12 pm',{'name':'necrotizing enterocolitis','verification_status':'confirmed','time':{'text':'around 12 pm','relation':'at','anchor':'NEC diagnosis'}},quote='the subsequent diagnosis of NEC occurring around 12 pm.')
 risk=b.obs('b00050','CoMET instability at NEC diagnosis',kind='physiologic',text_value='high risk, primarily respiratory instability; markedly increased over preceding 3 h',quote='Left: The patient’s CoMET is large and bright red at the time of NEC diagnosis, emphasizing the current high level of risk, primarily in respect of their risk of respiratory instability. The tail of the CoMET demonstrates that this instability has markedly increased over the previous 3 h.')
 e1=b.event('Stage 1 palliation',[surg],'b00050',quote='following stage 1 palliation and subsequent development of necrotizing enterocolitis (NEC)');e2=b.event('CoMET scores begin escalation',[rise],'b00050','around 9 am',quote='Note the escalation in CoMET scores starting around 9 am with the subsequent diagnosis of NEC occurring around 12 pm.');e3=b.event('NEC diagnosis with high primarily respiratory instability risk',[nec,diag,risk],'b00050','around 12 pm',quote='Note the escalation in CoMET scores starting around 9 am with the subsequent diagnosis of NEC occurring around 12 pm.');b.relation(e1,e3,'b00050',quote='following stage 1 palliation and subsequent development of necrotizing enterocolitis (NEC)');b.relation(e2,e3,'b00050',quote='Note the escalation in CoMET scores starting around 9 am with the subsequent diagnosis of NEC occurring around 12 pm.')
 b.summary('A 4-week-old infant with hypoplastic left syndrome underwent stage 1 palliation and subsequently developed NEC.',[ctx,age,hl,surg,nec]);b.summary('CoMET scores escalated around 9 am before NEC diagnosis around noon, with high primarily respiratory instability risk at diagnosis.',[rise,diag,risk])
 b.figure('Fig1','b00048',[('Left',[],'background','Cardiovascular and respiratory CoMET display with bed-number heads and 3-hour trajectory tails',None,None,None),('Right',[],'background','Joint risk display orders beds by composite score with recent tails',None,None,None)],scope='background',pids=[])
 b.figure('Fig2','b00049',[('a',[],'aggregate','Cardiovascular score versus VIS, linear fitted relationship',None,None,None),('b',[],'aggregate','Respiratory score versus VIS, nonlinear fitted relationship',None,None,None)],scope='aggregate',pids=[])
 b.figure('Fig3','b00050',[('Right',['p1'],'individual','Case trajectory display with cardiovascular red and respiratory green traces',None,None,None),('Left',['p1'],'individual','High risk primarily respiratory at NEC diagnosis; prior 3 h instability rise',None,None,None)])
 p['ambiguities']=[{'issue':'Caption diagnosis spelling','evidence':b.evidence('b00050','hypoplastic left syndrome'),'must_not_infer':'Do not silently add the word heart to the documented syndrome label.'}]
 b.limits+=['Only Fig3 caption provides individual patient information. Cohort demographics, outcome proportions, drug-related definitions and monitoring protocols were not assigned to this infant.','Individual medications, NEC stage, sex, laboratory values and follow-up outcome are not provided. CoMET numeric scores and pixels not inspected.']
