def eczema_cases():
 b=Builder('PMC13549756.1')
 for num,sid,age,sex in [(1,'b00008',3,'female'),(2,'b00009',7,'male'),(3,'b00010',5,'male')]:
  p=b.patient(f'Patient {num}, infant with severe exudative eczema',sid,quote=b.s[sid]['text'].split('. ')[0]+'.')
  b.fact('case_context',sid,f'Infant case {num} with severe eczema and electrolyte disturbance',{'case_kind':'clinical_case','species':'human','index_subject_description':p['label']},quote=b.s[sid]['text'].split('. ')[0]+'.')
  b.fact('demographics',sid,f'{age} months at presentation',{'attribute':'age_at_presentation','numeric_value':age,'unit':'months'},quote=f'{age} months'+(' of age' if num in [1,3] else ''))
  b.fact('demographics',sid,f'Documented {sex} pronoun',{'attribute':'documented_sex','text_value':sex},quote='She was exclusively breastfed' if num==1 else ('His eczema' if num==2 else 'He was admitted'))
  b.cond(sid,'Severe exudative eczema',severity='severe',quote=('severe, exudative eczema' if num==1 else 'infected and exudative' if num==2 else 'severe exudative eczema'))
  b.fact('conditions','b00012','Authors favor secondary physiological hyperaldosteronism',{'name':'secondary (physiological) hyperaldosteronism','verification_status':'provisional','diagnostic_basis':'RAAS activation with preserved renal sodium reabsorption'},quote='These cases suggest an association between severe AD and biochemical features of secondary (physiological) hyperaldosteronism—hyponatremia and hyperkalemia, with high renin and/or aldosterone levels and appropriate mineralocorticoid-driven renal reabsorption of sodium.',notes='Interpretive diagnosis; do not turn PHA-like urinary steroid profile into confirmed end-organ aldosterone resistance.')
  for condition in ['hypoalbuminemia','hypoproteinemia']:b.cond('b00014',condition,quote='This is consistent with our finding of hypoalbuminemia and hypoproteinemia in all 3 patients')
  b.obs('b00017','GFR',flag='normal',quote='GFR was normal in all 3 cases')
  b.obs(sid,'Renal function',flag='normal',quote='Her renal function and renal ultrasound were normal throughout' if num==1 else 'normal renal function' if num==2 else 'normal renal function including ultrasound')
  for med in ['emollients','1% hydrocortisone']+(['fusidic acid'] if num!=3 else []):b.med(sid,med,action='historical',route='topical',quote=med,notes='Pre-escalation regimen; efficacy failure documented in accompanying eczema facts.')
  if num==1:
   q='severe, exudative eczema unresponsive to emollients, 1% hydrocortisone and fusidic acid.';b.fact('outcomes',sid,'Initial topical treatment failed',{'event':'other','text_value':'eczema unresponsive to emollients, 1% hydrocortisone and fusidic acid'},q)
   for n,q in [('Reflux','longstanding reflux'),('Post-feed vomiting','vomiting after feeds'),('Severe aversive feeding','severe aversive feeding')]:b.symptom(sid,n,q)
   b.fact('social_exposures',sid,'Exclusive breastfeeding initially',{'domain':'diet','name':'exclusively breastfed'},quote='She was exclusively breastfed')
   b.fact('social_exposures',sid,'Mother excluded cow’s milk because of reflux and vomiting',{'domain':'diet','name':'cow’s milk excluded','subject':'mother'},quote='for which her mother had excluded cow’s milk from her diet.')
   b.fact('care_plans',sid,'Referred to allergy, dietetics and dermatology',{'action_text':'referral to allergy, dietetics, and dermatology','plan_type':'referral','action_status':'completed'},quote='The patient was referred to allergy, dietetics, and dermatology services')
   for m in ['Fucidin H','topical tacrolimus']:b.med(sid,m,action='started',route='topical' if 'topical' in m else None,quote='her treatment was escalated to include Fucidin H and topical tacrolimus.')
   b.fact('outcomes',sid,'Some eczema improvement at age 9 months',{'event':'improvement','text_value':'some improvement in eczema control','time':{'text':'9 months of age','relation':'at','anchor':'review'}},quote='On review at 9 months of age, there was some improvement in eczema control')
   b.fact('social_exposures',sid,'Predominantly breastfed with food allergen maternal exclusion at 9 months',{'domain':'diet','name':'predominantly breastfed with maternal allergen exclusion'},quote='she remained predominantly breastfed with severe aversive feeding, despite thickeners and exclusion of allergens from her mother’s diet after skin prick testing.')
   b.proc(sid,'Feed thickeners',quote='despite thickeners',kind='nonpharmacologic_therapy')
   b.obs(sid,'Weight centile',0.4,comparator='<',unit='centile',quote='Her weight dropped below the 0.4th centile')
   for n in ['iron','vitamin D']:b.cond(sid,n+' deficiency',quote='blood tests showed marked deficiencies of iron, vitamin D and sodium with severe hyperkalemia.')
   b.cond(sid,'Failure to thrive',quote='failure to thrive')
   admit=b.fact('outcomes',sid,'Admitted for electrolyte imbalance and failure to thrive',{'event':'other','text_value':'admission for supplementation and nasogastric feeding'},quote='Due to the acute electrolyte imbalance and failure to thrive, she was admitted for supplementation and nasogastric feeding.')
   b.proc(sid,'Nasogastric feeding',quote='she was admitted for supplementation and nasogastric feeding.')
   b.med(sid,'supplementation',quote='she was admitted for supplementation and nasogastric feeding.',notes='Supplement substances/doses not specified.')
