def acc_case():
 b=Builder('PMC13624887.1');p=b.patient('9-month-old girl with membranous scalp aplasia cutis congenita','b00002',quote='This article describes the case of a 9-month-old female patient with a rare form of membranous ACC.')
 b.fact('case_context','b00003','Referral for solitary asymptomatic congenital bullous scalp lesion',{'case_kind':'clinical_case','species':'human','index_subject_description':p['label'],'chief_complaint':'solitary and asymptomatic bullous scalp lesion'},quote='The patient was referred for the evaluation of a solitary and asymptomatic bullous lesion on the scalp.')
 b.fact('demographics','b00002','Age 9 months',{'attribute':'age_at_presentation','numeric_value':9,'unit':'months'},quote='9-month-old');b.fact('demographics','b00002','Female',{'attribute':'documented_sex','text_value':'female'},quote='female patient')
 lesion=b.symptom('b00003','Solitary bullous scalp lesion',kind='sign',body_site='right parasagittal scalp',text_value='translucent, round-shaped, clear-fluid-filled, 5 mm',quote='Physical examination revealed a 5 mm bullous lesion on the right parasagittal scalp region (Figure 1A). The lesion appeared translucent, round-shaped, and filled with clear fluid.')
 b.symptom('b00003','Asymptomatic lesion',kind='functional_status',text_value='asymptomatic',quote='a solitary and asymptomatic bullous lesion on the scalp')
 onset=b.fact('reproductive_perinatal','b00003','Scalp lesion present from birth',{'event':'congenital','text_value':'bullous scalp lesion present since birth'},quote='The lesion had been present since birth and remained stable over time.')
 stable=b.fact('outcomes','b00003','Lesion stable over time since birth',{'event':'other','text_value':'remained stable over time'},quote='The lesion had been present since birth and remained stable over time.')
 b.symptom('b00003','Associated systemic symptoms',assertion='absent',quote='No associated systemic symptoms or concomitant developmental anomalies were reported.')
 b.cond('b00003','Concomitant developmental anomalies',assertion='absent',quote='No associated systemic symptoms or concomitant developmental anomalies were reported.')
 b.fact('family_genetics','b00003','No relevant family history',{'kind':'family_condition','name':'relevant family history','assertion':'absent'},quote='There was no relevant family or prenatal history.')
 b.fact('reproductive_perinatal','b00003','No relevant prenatal history',{'event':'pregnancy','assertion':'absent','text_value':'No relevant prenatal history'},quote='There was no relevant family or prenatal history.',notes='Negates relevant prenatal history, not pregnancy itself.')
 b.obs('b00003','Clinical lesion diameter',5,kind='physiologic',unit='mm',body_site='right parasagittal scalp',quote='Physical examination revealed a 5 mm bullous lesion on the right parasagittal scalp region (Figure 1A).')
 derm=b.obs('b00003','Dermoscopy',kind='physiologic',text_value='fine arborizing vessels on translucent background; peripheral archlike hair roots/bulbs',quote='Dermoscopy demonstrated fine arborizing vessels overlying a translucent background, allowing visualization of hair roots and bulbs aligned in an archlike distribution at the periphery of the lesion (Figure 1B).')
 b.obs('b00003','Remainder of skin examination',kind='physiologic',flag='normal',quote='The remainder of the skin examination was unremarkable.')
 us=b.obs('b00003','Color Doppler ultrasound',kind='imaging',text_value='well-defined hypoechoic area measuring 5×15 mm',body_site='scalp',quote='Color Doppler ultrasonography revealed a well-defined hypoechoic area measuring 5×15 mm, with no signs of increased vascularity or underlying bone involvement.')
 b.obs('b00003','Doppler increased vascularity',kind='imaging',flag='negative',text_value='no increased vascularity',quote='with no signs of increased vascularity or underlying bone involvement.')
 b.obs('b00003','Underlying bone involvement on ultrasound',kind='imaging',flag='negative',text_value='no underlying bone involvement',quote='with no signs of increased vascularity or underlying bone involvement.')
 dx=b.cond('b00003','Membranous aplasia cutis congenita',role='primary_diagnosis',body_site='right parasagittal scalp',quote='The lesion was diagnosed as a membranous variant of ACC')
 conservative=b.proc('b00003','Conservative management',kind='nonpharmacologic_therapy',quote='a conservative approach with regular clinical follow-up was adopted.')
 plan=b.fact('care_plans','b00003','Regular clinical follow-up adopted',{'action_text':'regular clinical follow-up','plan_type':'follow_up','action_status':'planned'},quote='a conservative approach with regular clinical follow-up was adopted.')
 e1=b.event('Congenital lesion onset',[onset],'b00003','since birth',quote='The lesion had been present since birth and remained stable over time.');e2=b.event('Referral and clinical/dermoscopic/ultrasound evaluation',[lesion,derm,us,dx],'b00003');e3=b.event('Conservative management and follow-up plan',[conservative,plan],'b00003');b.relation(e1,e2,'b00003');b.relation(e2,e3,'b00003')
 b.summary('9-month-old girl with stable, solitary asymptomatic right parasagittal bullous scalp lesion present since birth; no systemic symptoms, developmental anomalies or relevant family/prenatal history.',[f['fact_id'] for f in p['facts'] if f['task'] in ['case_context','demographics','symptoms_function','reproductive_perinatal','family_genetics','outcomes']])
 b.summary('Dermoscopy and color Doppler findings supported membranous ACC; no increased vascularity or underlying bone involvement. Conservative management with regular follow-up adopted.',[f['fact_id'] for f in p['facts'] if f['task'] in ['observations','conditions','procedures_devices','care_plans']])
 b.figure('fig001','b00011',[('A',['p1'],'individual','Solitary clear-liquid-filled bullous scalp lesion','clinical photograph','scalp','A) Scalp solitary bullous lesion filled with clear liquid.'),('B',['p1'],'individual','Fine arborizing vessels/translucent background, peripheral arch-shaped hair roots/bulbs','dermoscopy','scalp','B) Dermoscopy shows fine arborizing vessels over a translucent background within which is possible to observe hair roots and hair bulbs arranged in an arch shape along the margins of the lesion.')])
 p['ambiguities']=[{'issue':'Clinical and ultrasound lesion dimensions differ','evidence':b.evidence('b00003','5 mm bullous lesion')+b.evidence('b00003','area measuring 5×15 mm'),'must_not_infer':'Different modality dimensions retained as stated; no correction or assumption of growth.'}]
 b.limits+=['No specific dressing or antibiotic ointment was documented for this patient; generic management recommendations excluded.','No MRI, histology, genetic testing or actual longitudinal outcome provided. Differential syndromes/neural tube defects are background, not patient diagnoses.']
 b.save(patient_segments=['b00002'])

def recovered_eczema_tables(b):
 # Original raw XML reviewed: Table1 columns3+2+2; urine subtable is Case1 and Case3 ONLY despite4-column span.
 ages=[['9 Mo','12 Mo','20 Mo'],['7 Mo','11 Mo'],['5 Mo','8 Mo']];offsets=[0,3,5]
 units=['mmol/L','mmol/L','pmol/L','nmol/L/hr','g/L','g/L','mmol/kg','×10^9/L','×10^9/L','umol/L','mmol/L']
 names=['Sodium','Potassium','Aldosterone','Renin','Albumin','Total protein','Serum osmolality','Platelets','WCC','Creatinine','Urea']
 merge={(0,0,'Sodium'):'Initial sodium',(0,0,'Potassium'):'Initial potassium',(0,2,'Aldosterone'):'Aldosterone at 20 months',(1,0,'Sodium'):'Sodium',(1,0,'Potassium'):'Potassium',(1,0,'Aldosterone'):'Aldosterone',(1,0,'Renin'):'Plasma renin activity',(1,0,'WCC'):'WBC',(2,0,'Sodium'):'Initial sodium',(2,0,'Potassium'):'Initial potassium',(2,0,'Aldosterone'):'Ward aldosterone after initial therapy',(2,0,'Renin'):'Ward renin after initial therapy',(2,0,'WCC'):'WBC'}
 for j,p in enumerate(b.p):
  b.cur=p;new=[];byage={x:[] for x in ages[j]}
  for n,u,sid in zip(names,units,[f'b{x:05}' for x in range(20,31)]):
   cols=b.s[sid]['text'].split('\n')[-1].split(' | ');ref=cols[1]
   for k,age in enumerate(ages[j]):
    val=cols[2+offsets[j]+k]
    if val in ['','-']:continue
    comp='<' if val.startswith('<') else '>' if val.startswith('>') else '=';num=float(val.lstrip('<>').replace(',',''))
    kw={'name':n+' at '+age,'kind':'laboratory','status':'resulted','numeric_value':num,'unit':u,'comparator':comp,'text_value':val,'reference_range_text':ref,'time':{'text':age,'relation':'at','anchor':'age in Table1'}}
    oldname=merge.get((j,k,n));old=next((f for f in p['facts'] if f['task']=='observations' and f['fields'].get('name')==oldname),None) if oldname else None
    if old:
     # Keep existing clinical occurrence name/flags; add recovered exact age, quantity/reference and evidence.
     old['fields'].update({a:v for a,v in kw.items() if a!='name'});old['evidence']+=b.evidence(sid);old['notes']+=' Recovered Table1 header/patient/age mapping verified in original raw XML.';fid=old['fact_id'];b.cover.setdefault(sid,set()).add(p['patient_id'])
     if j==2 and n in ['Aldosterone','Renin']:old['notes']+=' At-presentation5-month table column does not erase narrative that sampling followed ED sodium supplementation.'
    else:fid=b.fact('observations',sid,f'{n} at age {age}: {val} {u}',kw,notes='Full age-dependent reference ranges retained; no diagnosis inferred from range comparison.')
    new.append(fid);byage[age].append(fid)
  if j in [0,2]:
   tetra=b.obs('b00013','Urinary aldosterone precursor tetrahydroaldosterone',specimen='urine',text_value='relative increase reflecting mineralocorticoid pathway hyperstimulation',quote='the urinary steroid profiles (USPs) of cases 1 and 3 showed relative increases of corticosterone and aldosterone metabolites and the aldosterone precursor tetrahydroaldosterone, reflecting mineralocorticoid pathway hyperstimulation.');new.append(tetra)
  if j==2:
   abstract_resolution=b.fact('outcomes','b00001','Biochemical and hormonal disturbances resolved with skin/nutritional management',{'event':'improvement','text_value':'biochemical and hormonal disturbances resolved after dermatological and nutritional optimization'},quote='In each case, these biochemical and hormonal disturbances resolved after optimizing dermatological and nutritional management of their atopic presentations',notes='Abstract explicitly applies to every original case; detailed Case3 prose specifically reports renin normalization.');new.append(abstract_resolution)
  # Explicit urine header ownership governs merged cells, not apparent physical alignment under Case2 columns.
  if j in [0,2]:
   slot=2 if j==0 else 3;age='9 Mo' if j==0 else '5 Mo'
   for sid,n,u in [('b00032','Urinary sodium','mmol/L'),('b00033','Urinary osmolality','mmol/kg'),('b00034','Urinary steroid profile',None)]:
    val=b.s[sid]['text'].split('\n')[-1].split(' | ')[slot].split(' [rowspan=')[0]
    if val=='-':continue
    kw={'name':n+' in presentation urine subtable','kind':'laboratory','status':'resulted','specimen':'urine','time':{'text':'Case 1 (at presentation–9 mo)' if j==0 else 'Case 3 (at presentation–5 mo)','relation':'at','anchor':'presentation'},'text_value':val}
    if u:kw.update(numeric_value=float(val),unit=u)
    q=b.evidence(sid)+b.evidence('b00031')
    if j==0 and n=='Urinary sodium':
     old=next(f for f in p['facts'] if f['fields'].get('name')=='Urinary sodium');old['evidence']+=q;fid=old['fact_id'];b.cover.setdefault(sid,set()).add(p['patient_id']);b.cover.setdefault('b00031',set()).add(p['patient_id'])
    else:
     fid=b.fact('observations',sid,n+': '+val,kw,extra_ev=b.evidence('b00031'),notes='Urine subheader explicitly names Case1/Case3. Four-column Case3 span does not assign urine results to Case2.');b.cover.setdefault('b00031',set()).add(p['patient_id'])
    new.append(fid)
  growth=[]
  tage=[['Birth','9 Mo','20 Mo'],['Birth','7 Mo','11 Mo'],['Birth','5 Mo','8 Mo']][j]
  for sid,n,u in [('b00036','Weight','kg'),('b00037','Weight centile','centile')]:
   vals=b.s[sid]['text'].split('\n')[-1].split(' | ')[1:]
   for k,age in enumerate(tage):
    val=vals[j*3+k];kw={'name':n+' at '+age,'kind':'other','status':'resulted','unit':u,'time':{'text':age,'relation':'at','anchor':'birth' if age=='Birth' else 'age in Table2'},'text_value':val}
    if n=='Weight':kw.update(numeric_value=float(val))
    elif '–' not in val:kw.update(numeric_value=float(re.sub(r'[^0-9.]','',val)),comparator='<' if val.startswith('<') else '=')
    fid=b.fact('observations',sid,f'{n} at {age}: {val} {u}',kw,notes='Table2 header has three age columns per patient, verified in original raw XML.');growth.append(fid)
  for age,ids in byage.items():
   b.event('Recovered serial laboratory assessment at '+age,ids,'b00020',time=age)
  b.summary('Recovered tables provide serial electrolyte/endocrine, albumin/protein, renal, cell-count and osmolality values with reference ranges; measured birth/presentation/follow-up weights and centiles are retained individually.',new+growth)
  p['ambiguities'].append({'issue':'Urine subtable patient ownership with irregular span','evidence':b.evidence('b00031')+b.evidence('b00032'),'must_not_infer':'Subheaders identify Case1 and Case3 only; do not assign Case3 urine values to Case2 despite a four-column span covering that physical portion of the table.'})
  if j==0:
   p['ambiguities'] += [{'issue':'Prose tracking50th centile versus table59th at20months','evidence':b.evidence('b00008','her weight tracking the 50th centile')+b.evidence('b00037'),'must_not_infer':'Keep both narrative growth description and table59th; no invented reconciliation.'},{'issue':'Shared hypoproteinemia statement versus Case1 normal-range total protein','evidence':b.evidence('b00014','hypoalbuminemia and hypoproteinemia in all 3 patients')+b.evidence('b00025'),'must_not_infer':'Case1 total protein48/44g/L is within the table44–76g/L interval. Retain source statement as unresolved, not a newly confirmed range-derived diagnosis.'}]
   for f in p['facts']:
    if f['task']=='conditions' and f['fields'].get('name')=='hypoproteinemia':f.update(certainty='source_conflict',scoring='review_only',notes='Shared author statement conflicts with Case1 table values within supplied reference interval.')
 b.limits=[x for x in b.limits if not x.startswith('Tables 1 and 2 are referenced')]
 b.limits+=['Recovered Tables1/2 and original XML headers/spans reviewed. Urine subtable names Case1/Case3 only; dashes/blank cells are unreported, never negative results.','Age-specific serial table columns preserved separately from prose discharge-relative chronology; no sampling date reconciliation or range-derived disease assigned.']

def recovered_mirror_table(b):
 p=b.p[0];b.cur=p;facts=[];events=[]
 for sid,week,hours,days in [('b00016','Week 1',17,7),('b00017','Week 2',17,7),('b00018','Week 3',16,6)]:
  method=b.s[sid]['text'].split('\n')[-1].split(' | ')[1]
  f=b.proc(sid,week+' individual physiotherapist-accompanied rehabilitation',kind='nonpharmacologic_therapy',finding=method,time={'text':week,'relation':'during','anchor':'rehabilitation'},quote=b.s[sid]['text']);ids=[f]
  ids.append(b.obs(sid,week+' reported duration',hours,kind='other',unit='h',quote=b.s[sid]['text']))
  ids.append(b.obs(sid,week+' daily session duration',2.5,kind='other',unit='h',text_value='approximately 2.5 h',quote='Approximately 2.5 h'))
  ids.append(b.obs(sid,week+' frequency',days,kind='other',unit='days/week',quote=f'{days} days a week'))
  ids.append(b.obs(sid,week+' repetitions',10,kind='other',comparator='>=',unit='repetitions',quote='at least 10 repetitions'))
  facts+=ids;events.append(b.event(week+' rehabilitation regimen',ids,sid,time=week))
 b.relation(events[0],events[1],'b00017');b.relation(events[1],events[2],'b00018')
 b.summary('Recovered Table1 specifies individual physiotherapist-accompanied rehabilitation: week1 upper-limb functional movements with active lower limbs; weeks2/3 coordinated task-specific movements of all four limbs with gradual changes, at least 10 repetitions. Sessions were approximately 2.5 h/day for 7, 7, 6 days/week, with reported weekly totals 17, 17, 16 h.',facts)
 p['ambiguities'].append({'issue':'Approximate daily durations versus reported weekly totals','evidence':b.evidence('b00016')+b.evidence('b00017')+b.evidence('b00018'),'must_not_infer':'Do not replace reported17/17/16-hour totals with arithmetic from approximate2.5-hour sessions; retain both descriptions.'})
 b.limits=[x for x in b.limits if not x.startswith('Table1 rehabilitation plan is referenced')]
 b.limits+=['Recovered rehabilitation Table1 original XML read; approximate daily sessions, repetitions and reported weekly totals retained without arithmetic correction.']
